mapper.sql:
 from cynexus_appl_market.futures_position_member_rank m
 join cynexus_appl_market.futures_position_capture_batch b
   on b.id = m.capture_batch_id
  and b.deleted_at is null
  and b.selected is true
  and b.status in ('SUCCEEDED', 'PARTIAL')
where m.deleted_at is null
  and m.trade_date = #{tradeDate}


        and m.scope_type = 'CONTRACT'


        and m.scope_type = #{scopeType}



    and m.exchange_code = #{exchangeCode}


    and m.variety_code = #{varietyCode}

mapper.select:
with facts as ( select m.exchange_code, m.instrument_code, m.variety_code, m.contract_code, m.rank_type, m.rank_no, m.rank_value, m.rank_change, m.selected_source
), aggregated as ( select exchange_code,
variety_code instrument_code as instrument_code, max(variety_code) as variety_code,
cast(null as text) max(contract_code) as contract_code, sum(rank_value) filter (where rank_type = 'VOLUME' and rank_no <= #{top}) as volume, sum(rank_value) filter (where rank_type = 'LONG' and rank_no <= #{top}) as long_position, sum(rank_value) filter (where rank_type = 'SHORT' and rank_no <= #{top}) as short_position, sum(rank_change) filter (where rank_type = 'LONG' and rank_no <= #{top}) as long_change, sum(rank_change) filter (where rank_type = 'SHORT' and rank_no <= #{top}) as short_change, max(selected_source) as source from facts group by exchange_code,
variety_code instrument_code
) select exchange_code, instrument_code, variety_code, contract_code, volume, long_position, short_position, long_position - short_position as net_position, long_position / nullif(short_position, 0) as long_short_ratio, long_change, short_change, source from aggregated order by
volume long_position short_position long_position / nullif(short_position, 0) instrument_code long_position - short_position
asc nulls last desc nulls last
, instrument_code asc offset #{offset} limit #{limit}

choose.when:
with grouped as ( select m.trade_date, m.exchange_code, m.variety_code, m.rank_type, m.member_name, sum(m.rank_value) as rank_value, sum(coalesce(m.rank_change, 0)) as rank_change, max(m.selected_source) as source from cynexus_appl_market.futures_position_member_rank m join cynexus_appl_market.futures_position_capture_batch b on b.id = m.capture_batch_id and b.deleted_at is null and b.selected is true and b.status in ('SUCCEEDED', 'PARTIAL') where m.deleted_at is null and m.trade_date = #{tradeDate} and m.scope_type = 'CONTRACT' and m.exchange_code = #{exchangeCode} and m.variety_code = #{instrumentCode}
and m.rank_type = #{rankType}
group by m.trade_date, m.exchange_code, m.variety_code, m.rank_type, m.member_name ), ranked as ( select trade_date, exchange_code, variety_code, rank_type, member_name, row_number() over (partition by rank_type order by rank_value desc, member_name asc nulls last)::int as rank_no, rank_value, rank_change, source from grouped ) select trade_date, exchange_code, 'VARIETY' as scope_type, variety_code as instrument_code, variety_code, cast(null as text) as contract_code, rank_type, rank_no, member_name, rank_value, rank_change, source from ranked where rank_no <= #{top} order by rank_type asc, rank_no asc, member_name asc nulls last

choose.otherwise:
select m.trade_date, m.exchange_code, m.scope_type, m.instrument_code, m.variety_code,
       m.contract_code, m.rank_type, m.rank_no, m.member_name, m.rank_value, m.rank_change,
       m.selected_source as source
  from cynexus_appl_market.futures_position_member_rank m
  join cynexus_appl_market.futures_position_capture_batch b
    on b.id = m.capture_batch_id
   and b.deleted_at is null
   and b.selected is true
   and b.status in ('SUCCEEDED', 'PARTIAL')
 where m.deleted_at is null
   and m.trade_date = #{tradeDate}
   and m.scope_type = #{scopeType}
   and m.exchange_code = #{exchangeCode}
   and m.instrument_code = #{instrumentCode}
   and m.rank_no <= #{top}

   and m.rank_type = #{rankType}

 order by m.rank_type asc, m.rank_no asc, m.member_name asc nulls last

mapper.select:
with dates as ( select b.trade_date from cynexus_appl_market.futures_position_capture_batch b where b.deleted_at is null and b.selected is true and b.status in ('SUCCEEDED', 'PARTIAL') and b.exchange_code = #{exchangeCode}
and b.trade_date <= #{endDate}
order by b.trade_date desc limit #{limit} ), totals as ( select m.trade_date,
m.variety_code m.instrument_code as instrument_code, max(m.variety_code) as variety_code, sum(m.rank_value) filter (where m.rank_type = 'VOLUME' and m.rank_no <= #{top}) as volume, sum(m.rank_value) filter (where m.rank_type = 'LONG' and m.rank_no <= #{top}) as long_position, sum(m.rank_value) filter (where m.rank_type = 'SHORT' and m.rank_no <= #{top}) as short_position, sum(m.rank_change) filter (where m.rank_type = 'LONG' and m.rank_no <= #{top}) as long_change, sum(m.rank_change) filter (where m.rank_type = 'SHORT' and m.rank_no <= #{top}) as short_change, max(m.selected_source) as source from cynexus_appl_market.futures_position_member_rank m join dates d on d.trade_date = m.trade_date join cynexus_appl_market.futures_position_capture_batch b on b.id = m.capture_batch_id and b.deleted_at is null and b.selected is true and b.status in ('SUCCEEDED', 'PARTIAL') where m.deleted_at is null and m.exchange_code = #{exchangeCode}
and m.scope_type = 'CONTRACT' and m.variety_code = #{instrumentCode}
and m.scope_type = #{scopeType} and m.instrument_code = #{instrumentCode}
group by m.trade_date,
m.variety_code m.instrument_code
) select trade_date,
variety_code as instrument_code instrument_code , variety_code, volume, long_position, short_position, long_position - short_position as net_position, long_position / nullif(short_position, 0) as long_short_ratio, long_change, short_change, source from totals order by trade_date asc
